import { useEffect, useState } from "react"
import { Link, useLocation } from "react-router-dom"
import { Menu, X } from "lucide-react"
import { NAV_LINKS } from "@/data/site"

/** Small inline Union Jack used as the locale switch. */
function UkFlag({ className = "" }) {
  return (
    <svg viewBox="0 0 60 30" className={className} aria-hidden="true" focusable="false">
      <clipPath id="uk-flag-clip">
        <path d="M0 0v30h60V0z" />
      </clipPath>
      <g clipPath="url(#uk-flag-clip)">
        <path d="M0 0v30h60V0z" fill="#012169" />
        <path d="M0 0l60 30m0-30L0 30" stroke="#fff" strokeWidth="6" />
        <path d="M0 0l60 30m0-30L0 30" stroke="#c8102e" strokeWidth="4" />
        <path d="M30 0v30M0 15h60" stroke="#fff" strokeWidth="10" />
        <path d="M30 0v30M0 15h60" stroke="#c8102e" strokeWidth="6" />
      </g>
    </svg>
  )
}

export default function Header({ transparent = false }) {
  const [scrolled, setScrolled] = useState(false)
  const [menuOpen, setMenuOpen] = useState(false)
  const location = useLocation()

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 40)
    handleScroll()
    window.addEventListener("scroll", handleScroll, { passive: true })
    return () => window.removeEventListener("scroll", handleScroll)
  }, [])

  // Close the mobile drawer whenever the route changes.
  useEffect(() => {
    setMenuOpen(false)
  }, [location.pathname])

  const isOverHero = transparent && !scrolled && !menuOpen
  const shellClass = isOverHero
    ? "bg-transparent"
    : "bg-white shadow-[0_1px_20px_rgba(10,61,49,0.08)]"
  const textClass = isOverHero ? "text-white" : "text-forest"

  return (
    <header
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${shellClass}`}
    >
      <div className="mx-auto flex h-16 max-w-shell items-center justify-between px-[5%] md:h-20 xl:px-10">
        <Link
          to="/"
          className={`font-display text-xl tracking-tight transition-colors md:text-2xl ${textClass}`}
        >
          White &amp; Co.
        </Link>

        <nav aria-label="Main navigation" className="hidden items-center gap-7 lg:flex">
          {NAV_LINKS.map((link) => (
            <Link
              key={link.label}
              to={link.href}
              className={`font-body text-[11px] uppercase tracking-label transition-opacity hover:opacity-60 ${textClass} ${
                location.pathname === link.href ? "opacity-100" : "opacity-80"
              }`}
            >
              {link.label}
            </Link>
          ))}
        </nav>

        <div className="flex items-center gap-3 md:gap-5">
          <Link
            to="/blog"
            className={`hidden rounded-sm border px-5 py-2.5 font-display text-sm transition-colors md:inline-block ${
              isOverHero
                ? "border-white/70 text-white hover:bg-white hover:text-forest"
                : "border-forest/40 text-forest hover:bg-forest hover:text-white"
            }`}
          >
            Read Our Outlook
          </Link>

          <button
            type="button"
            className={`flex items-center transition-colors ${textClass}`}
            aria-label="Change region, currently United Kingdom"
          >
            <UkFlag className="h-4 w-7 rounded-[2px]" />
          </button>

          <button
            type="button"
            onClick={() => setMenuOpen((open) => !open)}
            aria-expanded={menuOpen}
            aria-controls="site-menu"
            aria-label={menuOpen ? "Close menu" : "Open menu"}
            className={`-mr-1 p-1 transition-colors ${textClass}`}
          >
            {menuOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
          </button>
        </div>
      </div>

      {menuOpen && (
        <div id="site-menu" className="border-t border-forest/10 bg-white">
          <nav
            aria-label="Menu"
            className="mx-auto flex max-w-shell flex-col px-[5%] py-6 xl:px-10"
          >
            {NAV_LINKS.map((link) => (
              <Link
                key={link.label}
                to={link.href}
                className="border-b border-forest/10 py-3 font-display text-lg text-forest"
              >
                {link.label}
              </Link>
            ))}
            <div className="mt-5 flex flex-wrap gap-x-6 gap-y-3">
              <Link to="/meet-the-team" className="font-body text-[11px] uppercase tracking-label text-forest/70">
                Meet The Team
              </Link>
              <Link to="/careers" className="font-body text-[11px] uppercase tracking-label text-forest/70">
                Careers
              </Link>
              <Link to="/contact" className="font-body text-[11px] uppercase tracking-label text-forest/70">
                Contact
              </Link>
              <Link to="/blog" className="font-body text-[11px] uppercase tracking-label text-forest/70">
                Read Our Outlook
              </Link>
            </div>
          </nav>
        </div>
      )}
    </header>
  )
}

import { useState } from "react"

export default function InquiryForm({ propertyId, onSubmit }) {
  const [formData, setFormData] = useState({
    full_name: "",
    email: "",
    phone: "",
    message: "",
    inquiry_type: "General",
  })
  const [submitting, setSubmitting] = useState(false)
  const [errors, setErrors] = useState({})

  const handleSubmit = async (e) => {
    e.preventDefault()

    // Basic validation
    const newErrors = {}
    if (!formData.full_name) newErrors.full_name = "Name is required"
    if (!formData.email) newErrors.email = "Email is required"
    if (!formData.message) newErrors.message = "Message is required"
    setErrors(newErrors)

    if (Object.keys(newErrors).length > 0) return

    setSubmitting(true)
    try {
      const data = {
        ...formData,
        property_id: propertyId,
        status: "New",
      }

      if (onSubmit) {
        await onSubmit(data)
      }

      setFormData({
        full_name: "",
        email: "",
        phone: "",
        message: "",
        inquiry_type: "General",
      })

      alert("Your inquiry has been sent! We'll contact you soon.")
    } catch (error) {
      console.error("Error submitting inquiry:", error)
      alert("There was an error sending your inquiry. Please try again.")
    } finally {
      setSubmitting(false)
    }
  }

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value })
    if (errors[e.target.name]) {
      setErrors({ ...errors, [e.target.name]: "" })
    }
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div>
          <label className="block font-body text-xs tracking-label uppercase text-muted-foreground mb-2">
            Full Name *
          </label>
          <input
            type="text"
            name="full_name"
            required
            value={formData.full_name}
            onChange={handleChange}
            className={`w-full px-4 py-3 border rounded-lg font-body text-sm ${
              errors.full_name ? "border-destructive" : "border-border"
            }`}
          />
          {errors.full_name && (
            <p className="text-destructive text-xs mt-1 font-body">{errors.full_name}</p>
          )}
        </div>

        <div>
          <label className="block font-body text-xs tracking-label uppercase text-muted-foreground mb-2">
            Email *
          </label>
          <input
            type="email"
            name="email"
            required
            value={formData.email}
            onChange={handleChange}
            className={`w-full px-4 py-3 border rounded-lg font-body text-sm ${
              errors.email ? "border-destructive" : "border-border"
            }`}
          />
          {errors.email && (
            <p className="text-destructive text-xs mt-1 font-body">{errors.email}</p>
          )}
        </div>
      </div>

      <div>
        <label className="block font-body text-xs tracking-label uppercase text-muted-foreground mb-2">
          Phone
        </label>
        <input
          type="tel"
          name="phone"
          value={formData.phone}
          onChange={handleChange}
          className="w-full px-4 py-3 border border-border rounded-lg font-body text-sm"
        />
      </div>

      <div>
        <label className="block font-body text-xs tracking-label uppercase text-muted-foreground mb-2">
          Inquiry Type
        </label>
        <select
          name="inquiry_type"
          value={formData.inquiry_type}
          onChange={handleChange}
          className="w-full px-4 py-3 border border-border rounded-lg font-body text-sm"
        >
          <option value="General">General Inquiry</option>
          <option value="Tour Request">Tour Request</option>
          <option value="Price Inquiry">Price Inquiry</option>
          <option value="Virtual Tour">Virtual Tour</option>
        </select>
      </div>

      <div>
        <label className="block font-body text-xs tracking-label uppercase text-muted-foreground mb-2">
          Message *
        </label>
        <textarea
          name="message"
          required
          rows={5}
          value={formData.message}
          onChange={handleChange}
          className={`w-full px-4 py-3 border rounded-lg font-body text-sm resize-none ${
            errors.message ? "border-destructive" : "border-border"
          }`}
        />
        {errors.message && (
          <p className="text-destructive text-xs mt-1 font-body">{errors.message}</p>
        )}
      </div>

      <button
        type="submit"
        disabled={submitting}
        className="w-full py-4 bg-foreground text-background font-body text-xs tracking-label uppercase hover:bg-foreground/90 transition-colors disabled:opacity-50"
      >
        {submitting ? "Sending..." : "Send Inquiry"}
      </button>
    </form>
  )
}

import { useEffect } from "react"
import { useLocation } from "react-router-dom"
import Header from "./Header"
import Footer from "./Footer"

/**
 * Site chrome shared by every route.
 *
 * `transparent` renders the header over a full-bleed hero (home page); every
 * other route gets the solid white header and matching top padding so content
 * is not hidden behind the fixed bar.
 */
export default function Layout({ children, transparent = false }) {
  const { pathname } = useLocation()

  // Reset scroll on navigation so a new page never opens mid-way down.
  useEffect(() => {
    window.scrollTo(0, 0)
  }, [pathname])

  return (
    <div className="flex min-h-screen flex-col bg-background">
      <Header transparent={transparent} />
      <main className={`flex-1 ${transparent ? "" : "pt-16 md:pt-20"}`}>{children}</main>
      <Footer />
    </div>
  )
}

import { motion } from "framer-motion"
import { Link } from "react-router-dom"
import { getBadgeForProperty } from "@/lib/badgeUtils"

export default function PropertyCard({ property, size = "default", badges: badgeProp }) {
  const badgeData = badgeProp || getBadgeForProperty(property)
  const badgeList = badgeData?.badges || []

  const sizeClasses = {
    default: "aspect-[4/3]",
    large: "aspect-[16/10] md:aspect-[21/9]",
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.5 }}
    >
      <Link to={`/property/${property.id}`} className="group block">
        <div className={`${sizeClasses[size] || sizeClasses.default} overflow-hidden rounded-lg bg-secondary`}>
          {property.featured_image && (
            <img
              src={property.featured_image}
              alt={property.title}
              className="h-full w-full object-cover object-center transition-transform duration-[1.2s] group-hover:scale-105"
            />
          )}
          {!property.featured_image && (
            <div className="h-full w-full flex items-center justify-center text-muted-foreground">
              No Image
            </div>
          )}
        </div>
        <div className="mt-4">
          <div className="flex items-start justify-between">
            <h3 className="font-display text-xl md:text-2xl font-light group-hover:text-accent transition-colors">
              {property.title}
            </h3>
            {badgeList.length > 0 && (
              <div className="flex gap-2">
                {badgeList.map((badge, i) => (
                  <span
                    key={i}
                    className={`text-xs px-2 py-1 rounded-full font-body ${
                      badge.variant === "destructive"
                        ? "bg-destructive text-destructive-foreground"
                        : badge.variant === "secondary"
                        ? "bg-secondary text-secondary-foreground"
                        : "bg-accent/20 text-accent"
                    }`}
                  >
                    {badge.label}
                  </span>
                ))}
              </div>
            )}
          </div>
          <p className="font-body text-muted-foreground mt-2 line-clamp-2">
            {property.description}
          </p>
          <div className="mt-3 flex items-center gap-4 font-body text-sm">
            <span className="font-display text-lg font-light">{property.price ? `$${property.price.toLocaleString()}` : "Price on request"}</span>
            <span className="text-muted-foreground">{property.bedrooms && `${property.bedrooms} bd`}</span>
            <span className="text-muted-foreground">{property.bathrooms && `${property.bathrooms} ba`}</span>
            <span className="text-muted-foreground">{property.sqft && `${property.sqft} sqft`}</span>
          </div>
        </div>
      </Link>
    </motion.div>
  )
}

import { Link } from "react-router-dom"
import { ChevronLeft, ChevronRight } from "lucide-react"

export default function PropertyFilters({ 
  currentFilters, 
  locations, 
  types, 
  priceRanges,
  listingTypes 
}) {
  const [filters, setFilters] = useState(currentFilters || {})

  const [sidebarOpen, setSidebarOpen] = useState(false)

  const updateFilter = (key, value) => {
    const newFilters = { ...filters, [key]: value }
    setFilters(newFilters)
    // Call parent callback
  }

  return (
    <div className="bg-secondary/30">
      <div className="max-w-[1400px] mx-auto px-[4%] md:px-[2%] py-6">
        <div className="flex items-center justify-between mb-4">
          <h3 className="font-display text-lg font-light">
            Filter Properties
          </h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
          {/* Location filter */}
          <select 
            className="px-4 py-3 border border-border rounded-lg font-body text-sm bg-background"
            value={filters.location || ""}
            onChange={(e) => updateFilter("location", e.target.value)}
          >
            <option value="">All Locations</option>
            {locations?.map((loc) => (
              <option key={loc} value={loc}>{loc}</option>
            ))}
          </select>

          {/* Type filter */}
          <select 
            className="px-4 py-3 border border-border rounded-lg font-body text-sm bg-background"
            value={filters.type || ""}
            onChange={(e) => updateFilter("type", e.target.value)}
          >
            <option value="">All Types</option>
            {types?.map((type) => (
              <option key={type} value={type}>{type}</option>
            ))}
          </select>

          {/* Price filter */}
          <select 
            className="px-4 py-3 border border-border rounded-lg font-body text-sm bg-background"
            value={filters.price || ""}
            onChange={(e) => updateFilter("price", e.target.value)}
          >
            <option value="">Any Price</option>
            {priceRanges?.map((range) => (
              <option key={range} value={range}>{range}</option>
            ))}
          </select>

          {/* Listing type filter */}
          <select 
            className="px-4 py-3 border border-border rounded-lg font-body text-sm bg-background"
            value={filters.listing || ""}
            onChange={(e) => updateFilter("listing", e.target.value)}
          >
            <option value="">Buy or Rent</option>
            {listingTypes?.map((lt) => (
              <option key={lt} value={lt}>{lt}</option>
            ))}
          </select>

          {/* Sort filter */}
          <select 
            className="px-4 py-3 border border-border rounded-lg font-body text-sm bg-background"
            value={filters.sort || ""}
            onChange={(e) => updateFilter("sort", e.target.value)}
          >
            <option value="-created_date">Newest First</option>
            <option value="price">Price: Low to High</option>
            <option value="-price">Price: High to Low</option>
          </select>
        </div>
      </div>
    </div>
  )
}

import { Link } from "react-router-dom"
import { ShieldCheck, UserCheck } from "lucide-react"

export default function ProtectedRoute({ children, requiredRole = "admin" }) {
  // This is a simple placeholder - you'd want to integrate this with
  // your actual auth system (Supabase Auth, Clerk, etc.)

  // Check if user is authenticated
  const isAuthenticated = false // Replace with actual auth check
  const hasRole = false // Replace with actual role check

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-white flex items-center justify-center py-24">
        <div className="text-center max-w-md px-4">
          <UserCheck size={48} className="mx-auto text-muted-foreground mb-6" />
          <h1 className="font-display text-2xl font-light mb-4">Authentication Required</h1>
          <p className="font-body text-muted-foreground mb-6">
            You need to be logged in to access this page.
          </p>
          <Link
            to="/login"
            className="inline-block px-6 py-3 bg-foreground text-background font-body text-xs tracking-label uppercase hover:bg-foreground/90 transition-colors"
          >
            Sign In
          </Link>
        </div>
      </div>
    )
  }

  if (requiredRole && !hasRole) {
    return (
      <div className="min-h-screen bg-white flex items-center justify-center py-24">
        <div className="text-center max-w-md px-4">
          <ShieldCheck size={48} className="mx-auto text-muted-foreground mb-6" />
          <h1 className="font-display text-2xl font-light mb-4">Access Denied</h1>
          <p className="font-body text-muted-foreground">
            You don't have permission to access this page.
          </p>
        </div>
      </div>
    )
  }

  return children
}

import { Circle, ShieldCheck, Clock } from "lucide-react"

const badges = [
  {
    label: "Verified",
    description: "Licensed & Insured",
    icon: ShieldCheck,
    variant: "default",
  },
